function solve(nums) {
  const n = nums.length;
  let best = 0;
  const used = new Array(n).fill(false);

  function rec(done, coins) {
    if (done === n) {
      if (coins > best) best = coins;
      return;
    }
    for (let i = 0; i < n; i++) {
      if (used[i]) continue;
      used[i] = true;
      let left = 1;
      for (let l = i - 1; l >= 0; l--) {
        if (!used[l]) { left = nums[l]; break; }
      }
      let right = 1;
      for (let r = i + 1; r < n; r++) {
        if (!used[r]) { right = nums[r]; break; }
      }
      rec(done + 1, coins + left * nums[i] * right);
      used[i] = false;
    }
  }

  rec(0, 0);
  return best;
}

function solve(nums) {
  const n = nums.length;
  if (n === 0) return 0;
  const arr = [1].concat(nums, [1]);
  const m = n + 2;
  const dp = [];
  for (let i = 0; i < m; i++) dp.push(new Array(m).fill(0));
  for (let len = 2; len < m; len++) {
    for (let i = 0; i + len < m; i++) {
      const j = i + len;
      let best = 0;
      for (let k = i + 1; k < j; k++) {
        const val = dp[i][k] + dp[k][j] + arr[i] * arr[k] * arr[j];
        if (val > best) best = val;
      }
      dp[i][j] = best;
    }
  }
  return dp[0][m - 1];
}
